-- Synthetic Bachs combined-order proof. No provider requests. Every fixture
-- and journal is rolled back before this statement succeeds.
do $campus_acceptance$
<<campus_acceptance>>
declare
 campus uuid; actor uuid; policy uuid; category uuid; buyer uuid=gen_random_uuid();s1 uuid=gen_random_uuid();s2 uuid=gen_random_uuid();a1 uuid=gen_random_uuid();a2 uuid=gen_random_uuid();p1 uuid=gen_random_uuid();p2 uuid=gen_random_uuid();app1 uuid=gen_random_uuid();app2 uuid=gen_random_uuid();order_id uuid=gen_random_uuid();qid uuid=gen_random_uuid();subject uuid;
 reference text='K1-B-O-ACCEPTANCE-'||gen_random_uuid();items jsonb;payload jsonb;pricing jsonb;snapshot jsonb;provider_quote jsonb;fee_profile app_private.bachs_fee_profiles;at_time timestamptz=now();expires timestamptz=now()+interval '2 minutes';fee bigint;result text;done boolean=false;before_users bigint;before_journals bigint;expected bigint;
begin
 select p.university_id,p.approved_by,p.id into campus,actor,policy from app_private.active_commerce_fee_policies a join app_private.commerce_fee_policies p on p.id=a.policy_id where p.kind='STORE' and app_private.bachs_collection_ready(p.university_id) limit 1;
 if campus is null then raise exception 'CAMPUS_ACCEPTANCE_REQUIRES_APPROVED_STORE_AND_BACHS';end if;
 select id into category from public.product_categories where university_id=campus and status='APPROVED' limit 1;
 if category is null then raise exception 'CAMPUS_ACCEPTANCE_REQUIRES_APPROVED_CATEGORY';end if;
 select count(*)into before_users from public.users;select count(*)into before_journals from public.ledger_transactions;
 begin
 foreach subject in array array[buyer,s1,s2]loop
 insert into public.users(id,email,password_hash,updated_at)values(subject,subject::text||'@acceptance.invalid','SYNTHETIC_ACCEPTANCE_ONLY',now());
 insert into public.profiles(id,user_id,university_id,username,display_name,updated_at)values(subject,subject,campus,'ko_'||substr(replace(subject::text,'-',''),1,20),'Self-cleaning campus acceptance',now());
 end loop;
 insert into public.agent_applications(id,user_id,university_id,agent_type,display_name,phone_e164,statement)values(app1,s1,campus,'VENDOR','Synthetic campus vendor one','+2348012345678','Self-cleaning acceptance only'),(app2,s2,campus,'VENDOR','Synthetic campus vendor two','+2348012345678','Self-cleaning acceptance only');
 insert into public.agent_profiles(id,user_id,university_id,application_id,agent_type,display_name,verified_at)values(a1,s1,campus,app1,'VENDOR','Synthetic campus vendor one',now()),(a2,s2,campus,app2,'VENDOR','Synthetic campus vendor two',now());
 insert into public.vendor_storefronts(vendor_profile_id,university_id,display_name,description,contact_phone_e164,pickup_location,opening_hours,status,submitted_at,moderated_revision,reviewed_at,reviewed_by_user_id,pickup_enabled)values(a1,campus,'Synthetic campus vendor one','Self-cleaning acceptance only','+2348012345678','Synthetic pickup one','{"Mon":"9am-5pm"}','APPROVED',now(),1,now(),actor,true),(a2,campus,'Synthetic campus vendor two','Self-cleaning acceptance only','+2348012345678','Synthetic pickup two','{"Mon":"9am-5pm"}','APPROVED',now(),1,now(),actor,true)on conflict(vendor_profile_id)do update set display_name=excluded.display_name,description=excluded.description,contact_phone_e164=excluded.contact_phone_e164,pickup_location=excluded.pickup_location,opening_hours=excluded.opening_hours,status=excluded.status,submitted_at=excluded.submitted_at,moderated_revision=excluded.moderated_revision,reviewed_at=excluded.reviewed_at,reviewed_by_user_id=excluded.reviewed_by_user_id,pickup_enabled=true;
 insert into public.vendor_products(id,university_id,vendor_profile_id,name,description,category,category_id,price_kobo,stock_quantity,status,submitted_at,moderated_revision,reviewed_at,reviewed_by_user_id,image_url,package_weight_grams,package_length_cm,package_width_cm,package_height_cm,bicycle_delivery_eligible)values(p1,campus,a1,'Synthetic item one','Self-cleaning acceptance only','Synthetic',category,100000,10,'PUBLISHED',now(),1,now(),actor,'https://example.invalid/synthetic-campus-product.jpg',300,10,10,10,true),(p2,campus,a2,'Synthetic item two','Self-cleaning acceptance only','Synthetic',category,200000,10,'PUBLISHED',now(),1,now(),actor,'https://example.invalid/synthetic-campus-product.jpg',300,10,10,10,true);
 insert into public.commerce_pickup_hubs(university_id,name,position)values(campus,'Synthetic acceptance hub',1000);
 items=jsonb_build_array(jsonb_build_object('product_id',p1,'quantity',1,'base_kobo',100000,'customer_unit_kobo',110000),jsonb_build_object('product_id',p2,'quantity',1,'base_kobo',200000,'customer_unit_kobo',220000));
 payload=jsonb_build_object('vendorProfileId',a1,'fulfilmentMode','PICKUP','pickupPointName','Synthetic acceptance hub','recipientName','Synthetic buyer','recipientPhoneE164','+2348012345678');
 pricing='{"baseKobo":300000,"listedItemsKobo":330000,"discountKobo":0,"sellerNetKobo":300000,"payableKobo":330000,"totalKobo":330000,"fareKobo":0,"cashDueKobo":0,"estimatedProcessingKobo":4950}'::jsonb;
 insert into app_private.store_checkout_quotes(id,university_id,buyer_user_id,vendor_profile_id,request_id,policy_id,request_payload,items,pricing,fare)values(order_id,campus,buyer,a1,gen_random_uuid(),policy,payload,items,pricing,null);
 perform * from app_private.create_priced_store_order(order_id,buyer,campus,'synthetic-pickup','synthetic-delivery');
 perform * from app_private.create_priced_store_order(order_id,buyer,campus,'synthetic-pickup','synthetic-delivery');
 if(select count(*)from app_private.order_vendor_allocations where order_vendor_allocations.order_id=campus_acceptance.order_id)<>2 or(select sum(seller_net_kobo)from app_private.order_vendor_allocations where order_vendor_allocations.order_id=campus_acceptance.order_id)<>300000 then raise exception 'COMBINED_ALLOCATION_FAILED';end if;
 if(select stock_quantity from public.vendor_products where id=p1)<>9 or(select stock_quantity from public.vendor_products where id=p2)<>9 then raise exception 'COMBINED_STOCK_REPLAY_FAILED';end if;
 insert into public.payment_attempts(id,user_id,university_id,resource_type,resource_id,provider_reference,amount_kobo,idempotency_key,status)values(gen_random_uuid(),buyer,campus,'STORE_ORDER',order_id,reference,330000,reference,'INITIALIZED');
 select i.snapshot into snapshot from app_private.bachs_purchase_intent(reference)i;
 select * into fee_profile from app_private.bachs_fee_profiles where university_id=campus and context='CHECKOUT_BANK_TRANSFER' and status='APPROVED' and effective_from<=now()order by effective_from desc,approved_at desc,id desc limit 1;
 fee=least(ceil(330000::numeric*(fee_profile.collection->>'basisPoints')::int/10000)::bigint,(fee_profile.collection->>'capKobo')::bigint);
 provider_quote=jsonb_build_object('provider','BACHS','currency','NGN','context',fee_profile.context,'profile',jsonb_build_object('id',fee_profile.id,'universityId',campus,'version',fee_profile.version,'context',fee_profile.context,'collection',fee_profile.collection,'status',fee_profile.status,'effectiveFrom',fee_profile.effective_from,'sourceUrl',fee_profile.source_url,'varianceToleranceKobo',fee_profile.variance_tolerance_kobo),'input',jsonb_build_object('subtotalKobo',330000,'priceMode','FIXED_TOTAL','expiresInMinutes',2),'createdAt',at_time,'expiresAt',expires,'subtotalKobo',330000,'discountPercent',0,'discountKobo',0,'discountedSubtotalKobo',330000,'deliveryKobo',0,'platformRevenueKobo',0,'rawRequirementKobo',330000,'pricingAdjustmentKobo',0,'includedProcessingKobo',0,'estimatedProviderFeeKobo',fee,'estimatedNetKobo',330000-fee,'finalCustomerAmountKobo',330000,'providerAmountKobo',330000);
 insert into app_private.bachs_checkout_quotes(id,user_id,university_id,resource_type,resource_id,provider_reference,resource_fingerprint,resource_snapshot,fee_profile_id,fee_profile_version,quote,created_at,expires_at)values(qid,buyer,campus,'STORE_ORDER',order_id,reference,encode(sha256(convert_to(snapshot::text,'UTF8')),'hex'),snapshot,fee_profile.id,fee_profile.version,provider_quote,at_time,expires);
 insert into app_private.bachs_priced_sessions(quote_id,checkout_id,provider_mode,checkout_url,expires_at)values(qid,'chk_campus_acceptance_'||qid,'test','https://sandbox-checkout.bachs.io/c/synthetic-acceptance',expires);
 perform app_private.record_bachs_pricing_receipt(qid,'test','ch_campus_acceptance_'||qid,330000,fee,at_time);
 result=app_private.record_priced_store_receipt(reference,330000,fee,at_time);if result<>'PAID' then raise exception 'COMBINED_RECEIPT_FAILED: %',result;end if;
 if app_private.record_priced_store_receipt(reference,330000,fee,at_time)<>'ALREADY_PAID' then raise exception 'COMBINED_RECEIPT_REPLAY_FAILED';end if;
 if app_private.finance_balance(campus,s1,'VENDOR_PENDING')<>100000 or app_private.finance_balance(campus,s2,'VENDOR_PENDING')<>200000 or app_private.finance_balance(campus,s1,'VENDOR_AVAILABLE')<>0 then raise exception 'COMBINED_PENDING_BALANCES_FAILED';end if;
 if app_private.coordinate_campus_order(order_id,gen_random_uuid(),'READY',null)<>'INVALID_STATE' then raise exception 'COMBINED_SCOPE_FAILED';end if;
 if app_private.coordinate_campus_order(order_id,campus,'READY',null)<>'OK' or app_private.coordinate_campus_order(order_id,campus,'COMPLETE','incorrect')<>'INCORRECT' then raise exception 'COMBINED_COORDINATION_FAILED';end if;
 if app_private.coordinate_campus_order(order_id,campus,'COMPLETE','synthetic-delivery')<>'OK' then raise exception 'COMBINED_HANDOFF_FAILED';end if;
 if app_private.finance_balance(campus,s1,'VENDOR_PENDING')<>0 or app_private.finance_balance(campus,s2,'VENDOR_PENDING')<>0 or app_private.finance_balance(campus,s1,'VENDOR_AVAILABLE')<>100000 or app_private.finance_balance(campus,s2,'VENDOR_AVAILABLE')<>200000 then raise exception 'COMBINED_RELEASE_FAILED';end if;
 if exists(select 1 from public.ledger_transactions t join public.ledger_lines l on l.transaction_id=t.id where t.university_id=campus and t.idempotency_key like '%'||reference||'%' group by t.id having sum(case when l.direction='DEBIT'then l.amount_kobo else-l.amount_kobo end)<>0)then raise exception 'COMBINED_JOURNAL_UNBALANCED';end if;
 done=true;raise exception using errcode='Z0001',message='CAMPUS_ACCEPTANCE_ROLLBACK';
 exception when sqlstate 'Z0001' then if not done or sqlerrm<>'CAMPUS_ACCEPTANCE_ROLLBACK' then raise;end if;
 end;
 if(select count(*)from public.users)<>before_users or(select count(*)from public.ledger_transactions)<>before_journals or exists(select 1 from public.orders where id=order_id)then raise exception 'CAMPUS_ACCEPTANCE_FIXTURE_LEAK';end if;
end $campus_acceptance$;
